private int parseEndOfLine(String headerPart,int end){
    if(headerPart==null) {
        return -1;
    }
    if(end<0 || end>=headerPart.length()){
        return -1;
    }
    int i=end;
    while(i<headerPart.length()-1){
        if(headerPart.charAt(i)=='\r' && headerPart.charAt(i+1)=='\n'){
            return i;
        }
        i++;
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || end < 0 || end >= headerPart.length()){
        return -1;
    }
    int length = headerPart.length();
    for(int i = end; i + 1 < length; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

