public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    try {
        if (file.isDirectory()) {
            deleteDirectoryOnExit(file);
        } else {
            file.deleteOnExit();
        }
    } catch (SecurityException se) {
        throw new IOException("Could not schedule deletion for " + file, se);
    }
}

private static void deleteDirectoryOnExit(File dir) throws IOException {
    File[] contents = dir.listFiles();
    if (contents != null) {
        for (File child : contents) {
            if (child.isDirectory()) {
                deleteDirectoryOnExit(child);
            } else {
                try {
                    child.deleteOnExit();
                } catch (SecurityException se) {
                    throw new IOException("Could not schedule deletion for file " + child, se);
                }
            }
        }
    }
    try {
        dir.deleteOnExit();
    } catch (SecurityException se) {
        throw new IOException("Could not schedule deletion for directory " + dir, se);
    }
}

