            return;
        }
        // Divide the vertices into two groups; arbitrary split at the midpoint
        int splitIndex = total / 2;
        List<V> group1 = vertices.subList(0, splitIndex);
        List<V> group2 = vertices.subList(splitIndex, total);
        // Ensure both groups are non-empty
