@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Partition vertices into two sets based on key naming convention.
    // Vertices starting with 'U'/'u' belong to the first part,
    // vertices starting with 'V'/'v' belong to the second part.
    // If the convention is not followed, we'll treat all vertices as part of the first set.
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (key == null || vertex == null) {
            continue; // skip invalid entries
        }
        if (key.length() > 0) {
            char first = key.charAt(0);
            if (first == 'U' || first == 'u') {
                left.add(vertex);
                continue;
            } else if (first == 'V' || first == 'v') {
                right.add(vertex);
                continue;
            }
        }
        // Default to left set if no clear distinction
        left.add(vertex);
    }

    // If either set is empty, we cannot form a bipartite graph.
    if (left.isEmpty() || right.isEmpty()) {
        return;
    }

    // Connect every vertex in left to every vertex in right.
    for (V u : left) {
        for (V v : right) {
            try {
                // addEdge might be overloaded; ignore returned edge object.
                target.addEdge(u, v);
            } catch (Exception e) {
                // Log or ignore; we don't want one failure to abort the whole construction.
                // e.printStackTrace(); // Optional debug
            }
        }
    }
}

