public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    // Compute the serialized size of the message
    int size = schema.getCachedSize(message);
    // Write the size as a varint32 prefix
    int tmp = size;
    while ((tmp & 0xFFFFFF80) != 0) {
        out.write((tmp & 0x7F) | 0x80);
        tmp >>>= 7;
    }
    out.write(tmp);
    // Now write the actual message data
    schema.writeTo(out, message, buffer);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || schema == null) {
        throw new NullPointerException("OutputStream and Schema cannot be null");
    }
    // Compute serialized size
    int size = schema.getSerializedSize(message);
    // Write size as a varint prefix
    int v = size;
    while ((v & ~0x7F) != 0) {
        out.write((v & 0x7F) | 0x80);
        v >>>= 7;
    }
    out.write(v);
    // Write the message itself
    CodedOutputStream cos = buffer != null
        ? CodedOutputStream.newInstance(out, buffer.remaining())
        : CodedOutputStream.newInstance(out);
    try {
        schema.serialize(message, cos);
    } finally {
        cos.flush();
    }
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) throw new IllegalArgumentException("OutputStream cannot be null");
    if (message == null) throw new IllegalArgumentException("Message cannot be null");
    if (schema == null) throw new IllegalArgumentException("Schema cannot be null");
    if (buffer == null) buffer = LinkedBuffer.allocate(128);

    // Encode the message into a byte array using the provided schema and buffer
    byte[] data = schema.encode(message, buffer);
    int length = data.length;

    // Write the length prefix in varint32 format
    int temp = length;
    while ((temp & 0xFFFFFF80) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);

    // Write the actual message bytes
    out.write(data);

    return length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    int size = schema.getCachedSize(message);
    // Determine the varint size needed to encode the length prefix
    int lengthPrefixSize = CodedOutputStream.computeInt32SizeNoTag(size);
    // Use the supplied LinkedBuffer or allocate a default one if null
    LinkedBuffer localBuffer = buffer != null ? buffer : LinkedBuffer.allocate(128);
    // Create a CodedOutputStream that writes to the provided OutputStream
    CodedOutputStream cos = CodedOutputStream.newInstance(out, lengthPrefixSize + size + localBuffer.remaining());
    try {
        cos.writeInt32NoTag(size);              // Write the length prefix
        schema.writeTo(message, cos);           // Serialize the message itself
        cos.flush();                            // Flush any remaining bytes
    } catch (IOException e) {
        throw e; // Rethrow IOException as specified
    }
    return size;
}

