public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterized = (ParameterizedType) genericType;
    Type[] rawArguments = parameterized.getActualTypeArguments();
    Class<?>[] result = new Class<?>[rawArguments.length];
    for (int i = 0; i < rawArguments.length; i++) {
        Type argument = rawArguments[i];
        if (argument instanceof Class<?>) {
            result[i] = (Class<?>) argument;
        } else if (argument instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) argument).getRawType();
            if (raw instanceof Class<?>) {
                result[i] = (Class<?>) raw;
            } else {
                // cannot resolve to a concrete class
                return null;
            }
        } else {
            // Contains a type variable or wildcard; resolution requires context not available
            return null;
        }
    }
    return result;
}

