public synchronized void send(final String message){  
    if(message == null){  
        return;  
    }  
    for (Client client : clients) {  
        try {  
            client.send(message);  
        } catch (Exception e) {  
            // If a client throws an exception we log and continue with others.  
            // Assuming a logger is available in the surrounding class.  
            if (logger != null) {  
                logger.warn("Failed to send message to client: {}", e.getMessage(), e);  
            }  
        }  
    }  
}

