protected List<TimeRange> buildTimeRanges(long start,long end){
    if (start > end) {
        throw new IllegalArgumentException("start must not be greater than end");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }
    if (start > end) {
        throw new IllegalArgumentException("Start time must not be after end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    try {
        while (currentStart < end) {
            long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
            ranges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd;
        }
    } catch (Exception ex) {
        throw new RuntimeException("Error building time ranges", ex);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non‑negative");
    }
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    try {
        long current = start;
        while (current < end) {
            long next = current + FETCH_DATA_DURATION;
            if (next > end) {
                next = end;
            }
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception ex) {
        // If any unexpected error occurs, wrap and rethrow as a runtime exception
        throw new RuntimeException("Error building time ranges", ex);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<TimeRange>();
    if (end <= start) {
        return ranges;
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end || next < 0) { // handle overflow or overshoot
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
        if (current == 0) { // defensive break in case of overflow
            break;
        }
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start < 0 || end < 0 || start > end){
        return ranges;
    }
    long current = start;
    while (current < end){
        long next;
        if (current > Long.MAX_VALUE - FETCH_DATA_DURATION){
            next = end;
        } else {
            next = Math.min(end, current + FETCH_DATA_DURATION);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

