static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket < 10000) {
        throw new IllegalArgumentException("timeBucket must be in yyyymmdd format");
    }
    int year = (int)(timeBucket / 10000L);
    int rem = (int)(timeBucket % 10000L);
    int month = rem / 100;
    int day = rem % 100;
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    int day = (int)(timeBucket % 100);
    if(day < 1){
        return timeBucket;
    }
    int compressedDay = 1 + ((day - 1) / dayStep) * dayStep;
    return timeBucket - day + compressedDay;
}

