public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int length = str.length();
    if (index < 0 || index > length) {
        return 0;
    }
    int end = index + len;
    if (end > length) {
        return 0;
    }
    int size = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                size += 4;
                i += 2;
                continue;
            }
        }
        int cp = ch;
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
        i += 1;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0) {
        return 0;
    }
    int start = Math.max(0, index);
    int end = Math.min(start + len, str.length());
    int size = 0;
    for (int i = start; i < end; ) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
            i++;
        } else if (c < 0x800) {
            size += 2;
            i++;
        } else if (Character.isHighSurrogate(c) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i += 2;
        } else {
            size += 3;
            i++;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int byteCount = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && (i + 1) < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                int codePoint = Character.toCodePoint(ch, low);
                byteCount += 4; // supplementary character
                i++; // skip low surrogate
                continue;
            }
        }
        if (ch <= 0x7F) {
            byteCount += 1;
        } else if (ch <= 0x7FF) {
            byteCount += 2;
        } else {
            byteCount += 3;
        }
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("index and len must be non-negative");
    }
    final int totalLen = str.length();
    if (index > totalLen) {
        throw new IllegalArgumentException("index out of bounds");
    }
    // Adjust len if it extends beyond the end of the sequence
    final int actualLen = (index + len > totalLen) ? (totalLen - index) : len;
    int byteCount = 0;
    int i = index;
    final int end = index + actualLen;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            byteCount += 1; // ASCII
        } else if (ch < 0x800) {
            byteCount += 2; // 2 bytes UTF‑8
        } else {
            if (Character.isHighSurrogate(ch)) {
                if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                    byteCount += 4; // surrogate pair
                    i++; // skip low surrogate
                } else {
                    // malformed surrogate, use replacement character U+FFFD (3 bytes)
                    byteCount += 3;
                }
            } else {
                byteCount += 3; // 3 bytes UTF‑8
            }
        }
        i++;
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    try {
        if (str == null) {
            return 0;
        }
        if (index < 0 || len < 0) {
            return 0;
        }
        int end = index + len;
        if (end > str.length()) {
            return 0;
        }
        int size = 0;
        for (int i = index; i < end; ) {
            int cp = str.codePointAt(i);
            if (cp <= 0x7F) {
                size += 1;
            } else if (cp <= 0x7FF) {
                size += 2;
            } else if (cp <= 0xFFFF) {
                size += 3;
            } else {
                size += 4;
            }
            i += Character.charCount(cp);
        }
        return size;
    } catch (Exception e) {
        return 0;
    }
}

