        // Assume the LinkedBuffer has a write(byte[], int, int) method
        lb.write(utf8, 0, utf8.length);
    } catch (Exception e) {
        // Fallback: write each character as its UTF-8 representation manually
        for (int i = 0; i < str.length(); i++) {
            int cp = str.codePointAt(i);
            if (Character.isHighSurrogate(str.charAt(i))) {
                i++; // skip low surrogate
            }
            byte[] bytes;
            if (cp < 0x80) {
                bytes = new byte[] { (byte) cp };
            } else if (cp < 0x800) {
                bytes = new byte[] {
                    (byte) (0xC0 | (cp >> 6)),
                    (byte) (0x80 | (cp & 0x3F))
                };
            } else if (cp <= 0xFFFF) {
                bytes = new byte[] {
                    (byte) (0xE0 | (cp >> 12)),
                    (byte) (0x80 | ((cp >> 6) & 0x3F)),
                    (byte) (0x80 | (cp & 0x3F))
                };
            } else {
                bytes = new byte[] {
                    (byte) (0xF0 | (cp >> 18)),
                    (byte) (0x80 | ((cp >> 12) & 0x3F)),
                    (byte) (0x80 | ((cp >> 6) & 0x3F)),
                    (byte) (0x80 | (cp & 0x3F))
                };
            }
            lb.write(bytes, 0, bytes.length);
        }
    }
    return lb;
}

