private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    if (str == null && suffix == null) return true;
    if (str == null || suffix == null) return false;
    if (suffix.length() > str.length()) return false;
    return str.regionMatches(ignoreCase, str.length() - suffix.length(), suffix, 0, suffix.length());
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Return true if both are null
    if (str == null && suffix == null) {
        return true;
    }
    // If either is null (but not both), return false
    if (str == null || suffix == null) {
        return false;
    }
    // If suffix length is greater than str, cannot end with it
    if (suffix.length() > str.length()) {
        return false;
    }
    // Compare the end of the string to the suffix
    if (ignoreCase) {
        return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    int strLen = str.length();
    if (suffixLen > strLen) {
        return false;
    }
    int toffset = strLen - suffixLen;
    return str.regionMatches(ignoreCase, toffset, suffix, 0, suffixLen);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) return suffix == null;
    if (suffix == null) return false;
    final int slen = str.length();
    final int suflen = suffix.length();
    if (suflen > slen) return false;
    return str.regionMatches(ignoreCase, slen - suflen, suffix, 0, suflen);
}

