    int i;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types only
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Skip array dimensions
            while (descriptor.charAt(i) == '[') {
                i++;
            }
            // Skip reference type fully
            if (descriptor.charAt(i) == 'L') {
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                // Skip the ';' that terminates the reference type
                i++;
            } else {
                // Primitive type: single character token
                i++;
            }
            // Perform the pop operation
            // Assume a field `int pos` exists representing the stack pointer
            // and that `pos` points to the next free slot.
            pos--;
        }
    } else {
        // Single type descriptor: just pop one
        pos--;
    }
}

private void pop(final String descriptor){
    try{
        int idx = descriptor.indexOf('(');
        if(idx!=-1){
            int end = descriptor.indexOf(')', idx);
            String params = descriptor.substring(idx+1, end);
            int i = 0;
            while(i < params.length()){
                char c = params.charAt(i);
                int size = 1;
                if(c == 'L'){
                    int sem = params.indexOf(';', i);
                    if(sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                    i = sem + 1;
                }else if(c == '['){
                    while(i < params.length() && params.charAt(i) == '[') i++;
                    if(i < params.length()){
                        if(params.charAt(i) == 'L'){
                            int sem = params.indexOf(';', i);
                            if(sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                            i = sem + 1;
                        }else{
                            i++;
                        }
                    }
                }else{
                    if(c == 'J' || c == 'D') size = 2;
                    i++;
                }
                for(int j=0; j<size; j++){
                    stack.pop();
                }
            }
        }else{
            int i = 0;
            while(i < descriptor.length()){
                char c = descriptor.charAt(i);
                int size = 1;
                if(c == 'L'){
                    int sem = descriptor.indexOf(';', i);
                    if(sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                    i = sem + 1;
                }else if(c == '['){
                    while(i < descriptor.length() && descriptor.charAt(i) == '[') i++;
                    if(i < descriptor.length()){
                        if(descriptor.charAt(i) == 'L'){
                            int sem = descriptor.indexOf(';', i);
                            if(sem == -1) throw new IllegalArgumentException("Invalid descriptor");
                            i = sem + 1;
                        }else{
                            i++;
                        }
                    }
                }else{
                    if(c == 'J' || c == 'D') size = 2;
                    i++;
                }
                for(int j=0; j<size; j++){
                    stack.pop();
                }
            }
        }
    }catch(Exception e){
        // ignore invalid descriptors
    }
}

