    }
    try {
        // Assume a field: Map<V, Map<V, E>> index
        if (index == null) {
            index = new HashMap<>();
        }
        Map<V, E> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
        targetMap.put(targetVertex, e);
    } catch (Exception ex) {
        throw new RuntimeException("Failed to add edge to index", ex);
    }
}

