    }
    try {
        // Assuming an existing field: Map<V, Map<V, List<E>>> edgeIndex;
        Map<V, List<E>> targetMap = edgeIndex.computeIfAbsent(sourceVertex, k -> new HashMap<>());
        List<E> edgeList = targetMap.computeIfAbsent(targetVertex, k -> new ArrayList<>());
        edgeList.add(e);
    } catch (Exception ex) {
        // Log the exception or rethrow as a runtime exception
        throw new RuntimeException("Failed to add edge to index", ex);
    }
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("sourceVertex, targetVertex and e must not be null");
    }
    try {
        // Add to the source vertex index
        if (index != null) {
            index.computeIfAbsent(sourceVertex, k -> new ArrayList<>()).add(e);
        }
        // If the graph is undirected or we also want reverse lookup, add to the target vertex index
        if (!sourceVertex.equals(targetVertex) && reverseIndex != null) {
            reverseIndex.computeIfAbsent(targetVertex, k -> new ArrayList<>()).add(e);
        } else if (!sourceVertex.equals(targetVertex) && index != null) {
            index.computeIfAbsent(targetVertex, k -> new ArrayList<>()).add(e);
        }
    } catch (RuntimeException ex) {
        throw new IllegalStateException("Failed to add edge to index", ex);
    }
}

