private void enlarge(final int size){
    if (size < 0){
        throw new IllegalArgumentException("size must be non-negative");
    }
    // No need to enlarge if the current capacity already satisfies the requirement
    int requiredCapacity = length + size;
    if (data.length >= requiredCapacity){
        return;
    }
    // Double the current capacity or use the required capacity, whichever is larger
    int newCapacity = Math.max(data.length << 1, requiredCapacity);
    // Handle potential integer overflow
    if (newCapacity <= 0 || newCapacity > Integer.MAX_VALUE - 5){
        newCapacity = Integer.MAX_VALUE - 5;
    }
    try{
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }catch(OutOfMemoryError e){
        // Re-throw to signal failure
        throw e;
    }
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int currentCap = data == null ? 0 : data.length;
    int requiredCap = length + size;
    int newCap = currentCap * 2;
    if (newCap < requiredCap) {
        newCap = requiredCap;
    }
    byte[] newArr = new byte[newCap];
    if (data != null && length > 0) {
        System.arraycopy(data, 0, newArr, 0, length);
    }
    data = newArr;
}

