public static String capitalize(String name){
    if (name == null || name.isEmpty()) {
        return name;
    }
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (first == upperFirst) {
        return name;
    }
    return upperFirst + name.substring(1);
}

public static String capitalize(String name) {
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the first two characters are uppercase, leave the string unchanged.
    if (len > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, convert the first character to uppercase.
    String first = Character.toString(name.charAt(0)).toUpperCase();
    return first + name.substring(1);
}

public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    // If the first character is already uppercase, return unchanged
    if (Character.isUpperCase(name.charAt(0))) {
        return name;
    }
    // Capitalize the first character and keep the rest unchanged
    return Character.toUpperCase(name.charAt(0)) + name.substring(1);
}

public static String capitalize(String name){
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    char first = name.charAt(0);
    if (len < 2) {
        return String.valueOf(Character.toUpperCase(first));
    }
    char second = name.charAt(1);
    if (Character.isUpperCase(first) && Character.isUpperCase(second)) {
        return name;
    }
    return String.valueOf(Character.toUpperCase(first)) + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput must not be null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Retrieve byte data and its length from the current buffer node.
        byte[] data = current.getBytes();   // user‑defined method returning the node’s byte array
        int length = current.getSize();     // user‑defined method returning the number of bytes in the array
        if (data != null && length > 0) {
            out.write(data, 0, length);
            totalSize += length;
        }
        current = current.getNext();        // user‑defined method returning the next buffer node
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    while (node != null) {
        byte[] buf = node.getBuffer();
        int len = node.size();
        out.write(buf, 0, len);
        total += len;
        node = node.next();
    }
    return total;
}

