private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is null");
    }
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("invalid index range: start=" + start + ", end=" + end);
    }
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        // Append a verification_type_info entry corresponding to the abstract type.
        // The JVMS format requires first a single byte tag followed by optional data.
        byte tag = type.getTag();
        stackMapTableEntries.writeByte(tag);
        switch (tag) {
            case AbstractTypeTag.INTEGER:
            case AbstractTypeTag.FLOAT:
            case AbstractTypeTag.LONG:
            case AbstractTypeTag.DOUBLE:
                // Primitive types only need the tag.
                break;
            case AbstractTypeTag.OBJECT:
                // OBJECT tags are followed by a CONSTANT_Class_info index.
                stackMapTableEntries.writeUnsignedShort(type.getOwnerIndex());
                break;
            case AbstractTypeTag.UNINITIALIZED:
                // UNINITIALIZED tags are followed by a u2 offset.
                stackMapTableEntries.writeUnsignedShort(type.getOffset());
                break;
            default:
                throw new IllegalArgumentException("Unsupported abstract type tag: " + tag);
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        // Retrieve the type description from the current frame
        TypeDescription type = currentFrame[i];
        // Convert the type to its JVMS verification_type_info representation
        VerificationTypeInfo vti = type.toVerificationTypeInfo();
        // Add the verification type info to the StackMapTable entries
        stackMapTableEntries.add(vti);
    }
}

private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null || stackMapTableEntries == null) {
        throw new IllegalStateException("Current frame or stack map table entries not initialized");
    }
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start/end indices: start=" + start + " end=" + end);
    }
    try {
        for (int i = start; i < end; i++) {
            AbstractType type = currentFrame[i];
            if (type == null) {
                continue;
            }
            switch (type.getKind()) {
                case OBJECT:
                    // verification_type_info tag 1
                    stackMapTableEntries.writeByte(0x01);
                    stackMapTableEntries.writeShort(type.getClassIndex());
                    break;
                case ARRAY:
                    // verification_type_info tag 7
                    stackMapTableEntries.writeByte(0x07);
                    stackMapTableEntries.writeByte(type.getDimensions());
                    stackMapTableEntries.writeShort(type.getClassIndex());
                    break;
                case UNINITIALIZED:
                    // verification_type_info tag 8
                    stackMapTableEntries.writeByte(0x08);
                    stackMapTableEntries.writeShort(type.getOffset());
                    break;
                default:
                    throw new IllegalStateException("Unsupported abstract type kind: " + type.getKind());
            }
        }
    } catch (Exception ex) {
        throw new RuntimeException("Failed to put abstract types into stack map table entries", ex);
    }
}

