public static int nextPrime(int desiredCapacity){ 
    try{ 
        if(desiredCapacity<=2) return 2; 
        int cap=desiredCapacity; 
        int max=desiredCapacity>=1000?(int)(desiredCapacity*1.11):Integer.MAX_VALUE; 
        while(true){ 
            if(isPrime(cap)) return cap; 
            cap++; 
            if(cap>max && desiredCapacity>=1000){ 
                max=cap+(int)(cap*0.11); 
            } 
        } 
    }catch(Exception e){ 
        return desiredCapacity>0?desiredCapacity:2; 
    } 
} 
private static boolean isPrime(int n){ 
    if(n<=1)return false; 
    if(n<=3)return true; 
    if(n%2==0||n%3==0)return false; 
    for(int i=5;i*i<=n;i+=6){ 
        if(n%i==0||n%(i+2)==0)return false; 
    } 
    return true; 
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be positive");
    }
    int n = Math.max(desiredCapacity, 2);
    // Helper to check primality
    java.util.function.IntPredicate isPrime = new java.util.function.IntPredicate() {
        @Override
        public boolean test(int value) {
            if (value < 2) return false;
            if (value == 2) return true;
            if ((value & 1) == 0) return false;
            int limit = (int) Math.sqrt(value);
            for (int i = 3; i <= limit; i += 2) {
                if (value % i == 0) return false;
            }
            return true;
        }
    };
    int maxBound = n;
    if (desiredCapacity >= 1000) {
        maxBound = (int) (desiredCapacity * 1.11) + 1;
    }
    while (n <= maxBound) {
        if (isPrime.test(n)) return n;
        n++;
    }
    // Fallback: continue searching beyond the bound if no prime was found within 11%
    while (true) {
        if (isPrime.test(n)) return n;
        n++;
    }
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int candidate = Math.max(2, desiredCapacity);
    if ((candidate & 1) == 0) candidate++; // make odd
    while (true) {
        boolean isPrime = true;
        for (int i = 3; i * i <= candidate; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
}

