    int candidate = desiredCapacity;
    // If candidate is even and greater than 2, make it odd to skip even numbers
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid overflow: if candidate is close to Integer.MAX_VALUE, break
        if (candidate > Integer.MAX_VALUE - 2) {
            // Return Integer.MAX_VALUE if it happens to be prime (rare)
            return Integer.MAX_VALUE;
        }
        candidate += 2; // skip even numbers
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if ((n & 1) == 0 || n % 3 == 0) return false;
    int limit = (int) Math.sqrt(n);
    for (int i = 5; i <= limit; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

