public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(str.length());
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < length) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    result.append('\b');
                    i++;
                    break;
                case 't':
                    result.append('\t');
                    i++;
