                case '\"':
                    result.append('\"');
                    i++;
                    break;
                case '\\':
                    result.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 < length) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            result.append((char) code);
                            i += 5; // skip \uXXXX
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid unicode escape sequence: \\u" + hex);
                        }
                    } else {
                        throw new Exception("Incomplete unicode escape sequence at end of string");
                    }
                    break;
                default:
                    // Octal escape: up to three octal digits 0-7
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int octal = next - '0';
                        int count = 1;
                        while (count < 3 && j + 1 < length) {
                            char nextOct = str.charAt(j + 1);
                            if (nextOct >= '0' && nextOct <= '7') {
                                octal = (octal << 3) + (nextOct - '0');
                                j++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        result.append((char) octal);
                        i = j;
                    } else {
                        // Unknown escape, keep as is
                        result.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
