public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
        } else {
            if (i == len - 1) {
                // Trailing backslash, just append it
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 6 <= len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5; // skip \"uXXXX"
                        } catch (NumberFormatException e) {
                            // Invalid, treat as literal
                            sb.append('u');
                            i++;
                        }
                    } else {
                        // Not enough characters, treat literally
                        sb.append('u');
                        i++;
                    }
                    break;
                default:
                    // Octal escape: up to three octal digits starting with 0-7
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = Math.min(j + 3, len);
                        int value = 0;
                        while (j < end && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                            value = (value << 3) + (str.charAt(j) - '0');
                            j++;
                        }
                        sb.append((char) value);
                        i = j - 1; // skip processed digits
                    } else {
                        // Unknown escape sequence, keep the next character literally
                        sb.append(next);
                        i++;
                    }
            }
        }
    }
    return sb.toString();
}

