private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // If array is null, create a new array of size 1 with the specified component type
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Both array and newArrayComponentType cannot be null");
        }
        // Element at index 0 will have the default value (null/0/false)
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    // Ensure the provided object is indeed an array
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array: " + arrayClass.getName());
    }

    Class<?> componentType = arrayClass.getComponentType();
    int length = java.lang.reflect.Array.getLength(array);

    // Create new array one element larger
    Object result = java.lang.reflect.Array.newInstance(componentType, length + 1);

    // Copy original elements
    System.arraycopy(array, 0, result, 0, length);

    // The element at index 'length' remains at its default value
    return result;
}

