            }
            return java.lang.reflect.Array.newInstance(newArrayComponentType,1);
        }
        Class<?> comp = array.getClass().getComponentType();
        int oldLen = java.lang.reflect.Array.getLength(array);
        Object newArr = java.lang.reflect.Array.newInstance(comp, oldLen + 1);
        System.arraycopy(array, 0, newArr, 0, oldLen);
        return newArr;
    }catch(Exception e){
        throw new RuntimeException(e);
    }
}

