private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    // Work on the smaller set to reduce work
    Set<V> result = new HashSet<>(set1.size() < set2.size() ? set1 : set2);
    // Keep only elements that are also in set2
    result.retainAll(set2);
    return result;
}

