    if (set1 == null || set2 == null) {
        return new HashSet<V>();
    }
    if (set1 == set2) {
        return new HashSet<V>(set1);
    }
    Set<V> result = new HashSet<V>();
    for (V element : set1) {
        if (set2.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

