private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    // Validate arguments
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node cannot be null");
    }

    // If the start is already the stop, return a circulator for the stop node
    if (start == stop) {
        return new OuterFaceCirculator(stop);
    }

    // Traverse nodes starting from 'start' until 'stop' is reached or a node satisfies the predicate.
    Node current = start;
    while (current != null && current != stop) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }

        // Move to the next node in the specified direction around the face.
        // Assumes Node has a method getNextInDirection(int dir) that returns the neighbour node.
        // If such a method does not exist, adjust the call accordingly to the actual API.
        try {
            current = current.getNextInDirection(dir);
        } catch (Exception e) {
            // If traversal method throws, break out to avoid infinite loop
            break;
        }
    }

    // If traversal completes without finding a node that satisfies the predicate,
    // return a circulator pointing to the stop node.
    return new OuterFaceCirculator(stop);
}

