private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    // Defensive checks for null arguments
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }
    // Ensure the direction is valid (-1 for backward, +1 for forward)
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be either 1 (forward) or -1 (backward)");
    }

    // Immediate return if the starting node already satisfies the predicate or is the stop node
    if (predicate.test(start) || start == stop) {
        return new OuterFaceCirculator(start, dir);
    }

    Node current = start;
    // Safety counter to avoid infinite loops; if more than 1024 steps without finding, break
    int safetyCounter = 0;
    final int MAX_STEPS = 1024;

    while (true) {
        // Stop if we reach the node that satisfies the predicate
        if (predicate.test(current)) {
            break;
        }
        // Stop if we reach the stop node
        if (current == stop) {
            break;
        }
        // Advance to the next node in the specified direction
        try {
            current = (dir == 1) ? current.next() : current.prev();
        } catch (Exception e) {
            // If traversal fails (e.g., no next/prev), break out
            break;
        }
        // If traversal returned to the start node without success, we are done
        if (current == null || current == start) {
            break;
        }
        safetyCounter++;
        if (safetyCounter >= MAX_STEPS) {
            // Avoid infinite loops in malformed data structures
            break;
        }
    }

    // Return a circulator either pointing at the found node or at the stop node
    return new OuterFaceCirculator(current, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Defensive checks
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node cannot be null");
    }

    // If start equals stop we can return a circulator pointing to stop immediately
    if (start == stop) {
        return new OuterFaceCirculator(stop, dir);
    }

    Node current = start;
    // Keep a counter to avoid infinite loops in case of malformed topology
    int visited = 0;
    final int maxVisited = 10000; // arbitrary large limit

    while (visited < maxVisited) {
        // If the current node satisfies the predicate, we found our target
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, dir);
        }
        // If we reached the stop node, return a circulator pointing to it
        if (current == stop) {
            return new OuterFaceCirculator(stop, dir);
        }

        // Advance to the next node in the specified direction.
        // We assume the Node class provides methods to walk along the outer face.
        // If the direction is positive, use the next neighbour; otherwise use the previous neighbour.
        try {
            current = (dir > 0) ? current.getNextOuterFace() : current.getPrevOuterFace();
            if (current == null) {
                // No further nodes; conservatively return a circulator at the stop node
                return new OuterFaceCirculator(stop, dir);
            }
        } catch (RuntimeException e) {
            // In case the underlying traversal throws an exception,
            // return a circulator at the stop node as a safe fallback.
            return new OuterFaceCirculator(stop, dir);
        }

        visited++;
    }

    // If we exceed the maximum number of iterations, return a circulator to the stop node.
    return new OuterFaceCirculator(stop, dir);
}

