public byte readByte() throws IOException {
    // Ensure the buffer is available
    if (buffer == null || buffer.length == 0) {
        throw new IOException("No buffer available");
    }

    // If the current buffer is exhausted, refill it from the underlying stream
    if (bufferPos >= bufferLimit) {
        try {
            bufferLimit = in.read(buffer);
            bufferPos = 0;
        } catch (Exception e) {
            throw new IOException("Failed to refill buffer", e);
        }

        // If nothing was read, end of stream has been reached
        if (bufferLimit <= 0) {
            throw new java.io.EOFException("End of stream reached");
        }
    }

    // Return the next byte and advance the position
    return buffer[bufferPos++];
}

