        if (aObj1 == null) {
            return -1;
        }
        if (aObj2 == null) {
            return 1;
        }

        // If both are Comparable, attempt to use compareTo
        if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
            try {
                // Suppress unchecked warning by casting to Comparable<?>
                Comparable<Object> comp1 = (Comparable<Object>) aObj1;
                Comparable<Object> comp2 = (Comparable<Object>) aObj2;
                return comp1.compareTo(comp2);
            } catch (ClassCastException | NullPointerException e) {
                // Fall back to other comparison strategy if types are not mutually comparable
            }
        }

        // Fallback: compare string representations
        String s1 = aObj1.toString();
        String s2 = aObj2.toString();
        return s1.compareTo(s2);

    } catch (Exception e) {
        // Wrap any unforeseen exception to avoid leaking unexpected runtime failures
        throw new RuntimeException("Failed to compare objects", e);
    }
}

