protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null) {
        throw new IllegalArgumentException("edge set tour is null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("graph is null");
    }
    if (tour.isEmpty()) {
        // create an empty path (start = end, no weight)
        return new org.jgrapht.graph.GraphPathImpl<>(null, null, 0.0, new java.util.ArrayList<>(), new java.util.ArrayList<>());
    }

    // Build an adjacency map of vertices to edges
    java.util.Map<V, java.util.List<E>> adj = new java.util.HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " not found in graph");
        }
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new java.util.ArrayList<>()).add(e);
        adj.computeIfAbsent(tgt, k -> new java.util.ArrayList<>()).add(e);
    }

    // Pick a start vertex: prefer one with degree 1; otherwise any vertex
    V start = null;
    for (java.util.Map.Entry<V, java.util.List<E>> entry : adj.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // cycle, pick arbitrary vertex from first edge
        E first = tour.iterator().next();
        start = graph.getEdgeSource(first);
    }

    java.util.List<V> vertices = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    java.util.Set<E> used = new java.util.HashSet<>();

    V current = start;
    vertices.add(current);

    while (used.size() < tour.size()) {
        java.util.List<E> edges = adj.getOrDefault(current, java.util.Collections.emptyList());
        E nextEdge = null;
        for (E e : edges) {
            if (!used.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            // no more unused edges from current vertex
            break;
        }
        used.add(nextEdge);
        edgeList.add(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(current)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        vertices.add(next);
        current = next;
    }

    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }

    // Construct and return the GraphPath
    return new org.jgrapht.graph.GraphPathImpl<>(start, current, totalWeight, edgeList, vertices);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Basic validation
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null; // or throw exception if preferred
    }
    // Use lists to preserve order
    java.util.List<V> vertices = new java.util.ArrayList<>();
    java.util.List<E> edges = new java.util.ArrayList<>();
    java.util.Set<E> remaining = new java.util.LinkedHashSet<>(tour);
    // Start with an arbitrary edge
    E startEdge = remaining.iterator().next();
    remaining.remove(startEdge);
    V source = graph.getEdgeSource(startEdge);
    V target = graph.getEdgeTarget(startEdge);
    vertices.add(source);
    vertices.add(target);
    edges.add(startEdge);
    // Continue traversing until all edges are used
    while (!remaining.isEmpty()) {
        V current = vertices.get(vertices.size() - 1);
        E nextEdge = null;
        for (E e : remaining) {
            V eSrc = graph.getEdgeSource(e);
            V eTgt = graph.getEdgeTarget(e);
            if (eSrc.equals(current) || eTgt.equals(current)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            // No connecting edge found; cannot form a continuous tour
            throw new IllegalStateException("Edge set does not form a continuous tour");
        }
        // Determine the new vertex to add
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        vertices.add(nextVertex);
        edges.add(nextEdge);
        remaining.remove(nextEdge);
    }
    // Compute total weight
    double totalWeight = 0.0;
    for (E e : edges) {
        totalWeight += graph.getEdgeWeight(e);
    }
    // Return an anonymous GraphPath implementation
    return new GraphPath<V, E>() {
        public List<V> getVertexList() {
            return java.util.Collections.unmodifiableList(vertices);
        }
        public List<E> getEdgeList() {
            return java.util.Collections.unmodifiableList(edges);
        }
        public double getWeight() {
            return totalWeight;
        }
    };
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null; // empty tour results in no path
    }
    try {
        List<E> orderedEdges = new ArrayList<>();
        Iterator<E> it = tour.iterator();
        E first = it.next();
        orderedEdges.add(first);
        Set<E> remaining = new HashSet<>(tour);
        remaining.remove(first);
        E lastEdge = first;
        while (!remaining.isEmpty()) {
            boolean found = false;
            for (E e : new HashSet<>(remaining)) {
                V srcL = graph.getEdgeSource(lastEdge);
                V tgtL = graph.getEdgeTarget(lastEdge);
                V srcR = graph.getEdgeSource(e);
                V tgtR = graph.getEdgeTarget(e);
                if (tgtL.equals(srcR) || tgtL.equals(tgtR) || srcL.equals(srcR) || srcL.equals(tgtR)) {
                    orderedEdges.add(e);
                    remaining.remove(e);
                    lastEdge = e;
                    found = true;
                    break;
                }
            }
            if (!found) {
                // cannot order edges into a continuous path
                throw new RuntimeException("Provided edges cannot form a continuous tour");
            }
        }
        return new GraphPath<>(graph, orderedEdges);
    } catch (Exception e) {
        // In case of any exception, return null or rethrow as unchecked
        return null;
    }
}

