private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            if (next == '.') {
                sb.append('.');
            } else if (next == '\\') {
                sb.append('\\');
            } else {
                // If backslash is escaping any other character, just include the escaped character
                sb.append(next);
            }
            i++; // skip the escaped character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1,String[] array2){
    // If both arrays are null, return null
    if (array1 == null && array2 == null) {
        return null;
    }
    // If one array is null, return a copy of the other to avoid accidental modification
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }
    // Both arrays are non-null; concatenate them
    int totalLength = array1.length + array2.length;
    String[] result = new String[totalLength];
    System.arraycopy(array1, 0, result, 0, array1.length);
    System.arraycopy(array2, 0, result, array1.length, array2.length);
    return result;
}

