private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel cannot be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return; // nothing to move
    }
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }
    // Use a copy to avoid concurrent modification if minBucket is same as zeroBucket
    for (Integer vertex : new HashSet<>(minBucket)) {
        zeroBucket.add(vertex);
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    minBucket.clear();
}

