private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel){
    // Validate inputs
    if (bucketsByLabel == null || labels == null){
        throw new IllegalArgumentException("bucketsByLabel and labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()){
        throw new IllegalArgumentException("minLabel out of bounds");
    }

    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    if (sourceBucket == null || sourceBucket.isEmpty()){
        // Nothing to move
        return;
    }

    // Ensure destination bucket (label 0) exists
    Set<Integer> destBucket = bucketsByLabel.get(0);
    if (destBucket == null){
        destBucket = new HashSet<>();
        // make sure list has a bucket at index 0
        if (bucketsByLabel.isEmpty()){
            // fill list with nulls up to index 0
            while (bucketsByLabel.size() <= 0){
                bucketsByLabel.add(null);
            }
        }
        bucketsByLabel.set(0, destBucket);
    }

    // Move vertices and update labels
    try{
        for (Integer vertex : sourceBucket){
            destBucket.add(vertex);
            if (vertex != null && vertex >= 0 && vertex < labels.size()){
                labels.set(vertex, 0);
            }
        }
    } catch (Exception e){
        // In case of concurrent modification or index issue, rethrow as runtime
        throw new RuntimeException("Failed to reload buckets", e);
    }

    // Clear the source bucket
    sourceBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    try {
        if (bucketsByLabel == null || labels == null) {
            return;
        }
        if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
            return;
        }
        if (minLabel == 0) { // moving to the same bucket; nothing to do
            return;
        }
        Set<Integer> source = bucketsByLabel.get(minLabel);
        if (source == null || source.isEmpty()) {
            return;
        }

        // Ensure destination bucket at index 0 exists
        Set<Integer> dest = bucketsByLabel.get(0);
        if (dest == null) {
            dest = new java.util.HashSet<>();
            if (bucketsByLabel.isEmpty()) {
                bucketsByLabel.add(dest);
            } else {
                bucketsByLabel.set(0, dest);
            }
        }

        // Move vertices and update labels
        for (Integer v : new java.util.ArrayList<>(source)) {
            if (v == null) continue;
            dest.add(v);
            if (v >= 0 && v < labels.size()) {
                labels.set(v, 0);
            }
        }

        // Clear the old bucket
        source.clear();
    } catch (Exception e) {
        // Ignore any unexpected errors
    }
}

