    if (buffer == null) {
        throw new IllegalArgumentException("buffer cannot be null");
    }
    if (fieldName == null) {
        fieldName = "";
    }
    buffer.append(fieldName);
    buffer.append("=[");
    if (array != null) {
        for (int i = 0; i < array.length; i++) {
            buffer.append(String.format("%02X", array[i]));
            if (i < array.length - 1) {
                buffer.append(',');
            }
        }
    } else {
        buffer.append("null");
    }
    buffer.append("]");
}

