    if (array == null) {
        throw new IllegalArgumentException("array must not be null");
    }
    try {
        buffer.append('[');
        for (int i = 0; i < array.length; i++) {
            if (i > 0) {
                buffer.append(',');
            }
            // Represent each byte in two-digit hexadecimal format
            buffer.append(String.format("%02X", array[i]));
        }
        buffer.append(']');
    } catch (Exception e) {
        // Fallback: just append a placeholder indicating failure
        buffer.append("[error displaying byte array]");
    }
}

