protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    // Validate the buffer reference; it must not be null
    if (buffer == null) {
        throw new IllegalArgumentException("buffer cannot be null");
    }
    // fieldName may be null; default to the string "null" for readability
    if (fieldName == null) {
        fieldName = "null";
    }
    try {
        buffer.append(fieldName);
        buffer.append(": [");
        // Iterate over the byte array and append each element
        for (int i = 0; i < array.length; i++) {
            buffer.append(array[i]); // directly append decimal value
            if (i < array.length - 1) {
                buffer.append(", ");
            }
        }
        buffer.append("]");
    } catch (Exception e) {
        // If anything unexpected occurs, record the error inside the buffer
        buffer.append(fieldName);
        buffer.append(": [Error: ");
        buffer.append(e.toString());
        buffer.append("]");
    }
}

