private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non‑negative");
    }
    if (elements > pos) {
        throw new IllegalStateException("Not enough elements on the stack to pop");
    }
    pos -= elements;
}

private void pop(final int elements){
    if (elements <= 0) {
        return;
    }
    if (elements > pos) {
        throw new IllegalArgumentException("Attempting to pop " + elements + " elements, but only " + pos + " available");
    }
    for (int i = pos - elements; i < pos; i++) {
        stack[i] = null;
    }
    pos -= elements;
}

