private void pop(final int elements){
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non-negative");
    }
    if (elements > pos) {
        throw new IllegalStateException(
                "Stack underflow: requested " + elements + " pops but only " + pos + " elements on stack");
    }
    // Optionally clear references for GC
    for (int i = 0; i < elements; i++) {
        stack[pos - i - 1] = null;
    }
    pos -= elements;
}

private void pop(final int elements){
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non-negative");
    }
    if (elements > pos) {
        throw new IllegalStateException("Attempt to pop more elements than present on the stack");
    }
    pos -= elements;
}

public boolean isCompatible(DataTable dataset){
    if (dataset == null) {
        return false;
    }
    try {
        // try to get bucket via a `getBucket` method
        java.lang.reflect.Method getBucketMethod = dataset.getClass().getMethod("getBucket");
        Object dataBucket = getBucketMethod.invoke(dataset);
        // obtain current object's bucket
        java.lang.reflect.Method thisMethod = this.getClass().getMethod("getBucket");
        Object thisBucket = thisMethod.invoke(this);
        return java.util.Objects.equals(thisBucket, dataBucket);
    } catch (Exception e) {
        // Attempt reflection on a field named 'bucket'
        try {
            java.lang.reflect.Field thisField = this.getClass().getDeclaredField("bucket");
            thisField.setAccessible(true);
            Object thisBucket = thisField.get(this);
            java.lang.reflect.Field dataField = dataset.getClass().getDeclaredField("bucket");
            dataField.setAccessible(true);
            Object dataBucket = dataField.get(dataset);
            return java.util.Objects.equals(thisBucket, dataBucket);
        } catch (Exception ex) {
            // Unable to determine buckets; consider not compatible
            return false;
        }
    }
}

