private Class findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className must not be null");
    }
    return Class.forName(className);
}

private Class findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className must not be null");
    }
    ClassLoader cl = Thread.currentThread().getContextClassLoader();
    if (cl != null) {
        try {
            return Class.forName(className, true, cl);
        } catch (ClassNotFoundException e) {
            // Fallback to the system class loader if the context loader fails
            return Class.forName(className);
        }
    } else {
        // If no context class loader is available, use the system loader
        return Class.forName(className);
    }
}

private Class findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className must not be null");
    }
    ClassLoader cl = Thread.currentThread().getContextClassLoader();
    if (cl == null) {
        cl = ClassLoader.getSystemClassLoader();
    }
    return Class.forName(className, true, cl);
}

private Class findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className must not be null");
    }
    try {
        ClassLoader cl = Thread.currentThread().getContextClassLoader();
        if (cl != null) {
            return Class.forName(className, true, cl);
        } else {
            return Class.forName(className);
        }
    } catch (ClassNotFoundException e) {
        throw e;
    } catch (LinkageError | NoClassDefFoundError err) {
        throw new ClassNotFoundException("Class not found due to linkage error: " + className, err);
    }
}

