public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        return;
    }
    // Retrieve the name to abbreviate.  
    // This assumes a getName() method or a field named 'name' exists in the same class.
    String name = null;
    try {
        name = getName();
    } catch (NoSuchMethodError e) {
        // Fallback: attempt to access a field named 'name' via reflection.
        try {
            java.lang.reflect.Field field = this.getClass().getDeclaredField("name");
            field.setAccessible(true);
            Object value = field.get(this);
            if (value instanceof String) {
                name = (String) value;
            }
        } catch (Exception ex) {
            // If no name could be retrieved, nothing to abbreviate.
            return;
        }
    }
    if (name == null || name.isEmpty()) {
        return;
    }
    int startIndex = Math.max(0, nameStart);
    if (startIndex >= name.length()) {
        return;
    }

    boolean startOfWord = true;
    for (int i = startIndex; i < name.length(); i++) {
        char ch = name.charAt(i);
        if (startOfWord && Character.isLetterOrDigit(ch)) {
            buf.append(Character.toUpperCase(ch));
            startOfWord = false;
        }
        if (ch == ' ' || ch == '-' || ch == '_' || ch == '/') {
            startOfWord = true;
        }
    }
}

