public void abbreviate(final int nameStart, final StringBuffer buf) {
    try {
        // Assume there is a field named 'name' that holds the full name string
        String fullName = this.name;
        if (fullName == null) {
            return;
        }
        if (nameStart < 0 || nameStart >= fullName.length()) {
            return;
        }
        // Extract the name to abbreviate starting from nameStart
        String nameToAbbreviate = fullName.substring(nameStart).trim();
        if (nameToAbbreviate.isEmpty()) {
            return;
        }
        // Split into parts (words) and abbreviate each part to its initial letter
        String[] parts = nameToAbbreviate.split("\\s+");
        for (int i = 0; i < parts.length; i++) {
            if (!parts[i].isEmpty()) {
                buf.append(parts[i].charAt(0)).append('.');
                if (i < parts.length - 1) {
                    buf.append(' ');
                }
            }
        }
    } catch (Exception e) {
        // In case of any error, do not add anything to buf
        // Optionally log the exception here
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    try{
        if(buf==null) return;
        if(this.name==null) return;
        int len=this.name.length();
        if(nameStart<0 || nameStart>=len) return;
        int idx=nameStart;
        boolean newWord=true;
        while(idx<len){
            char ch=this.name.charAt(idx);
            if(Character.isLetterOrDigit(ch)){
                if(newWord){
                    buf.append(Character.toUpperCase(ch));
                    buf.append('.');
                    newWord=false;
                }
            }else{
                if(Character.isWhitespace(ch)){
                    newWord=true;
                }else{ // treat non-space separators as word boundaries
                    newWord=true;
                }
            }
            idx++;
        }
    }catch(Exception e){
        // ignore exceptions
    }
}

