private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("graph and vertices must not be null");
    }
    for (V v1 : vertices) {
        if (v1 == null) {
            throw new IllegalArgumentException("vertices set contains null");
        }
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            try {
                if (graph.getEdge(v1, v2) == null) {
                    return false;
                }
            } catch (Exception e) {
                // Any exception during edge lookup indicates the pair is not connected
                return false;
            }
        }
    }
    return true;
}

