private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null || vertices == null){
        return false;
    }
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V v1 = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = list.get(j);
            if (graph.getEdge(v1, v2) == null && graph.getEdge(v2, v1) == null) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null.");
    }
    // An empty set or a single vertex is trivially a clique.
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                E edge = graph.getEdge(v1, v2);
                if (edge == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
            bounds.add(null);
            continue;
        }
        Integer maxLower = null;
        for (K other : keys) {
            if (other == null || other.equals(key)) {
                continue;
            }
            try {
                @SuppressWarnings("unchecked")
                Comparable<K> cmp = (Comparable<K>) other;
                if (cmp.compareTo(key) < 0) {
                    Integer val = null;
                    if (other instanceof Number) {
                        val = ((Number) other).intValue();
                    }
                    if (val != null) {
                        if (maxLower == null || val > maxLower) {
                            maxLower = val;
                        }
                    }
                }
            } catch (ClassCastException e) {
                // other not comparable to key; ignore
            }
        }
        bounds.add(maxLower);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) return result;
    for (K key : keys){
        Integer best = null;
        if (key == null){ result.add(null); continue; }
        for (K other : keys){
            if (other == null || key.equals(other)) continue;
            int cmp;
            try{
                cmp = ((Comparable)other).compareTo(key);
            }catch(ClassCastException e){
                continue;
            }
            if (cmp < 0){
                Integer val;
                try{
                    val = ((Number)other).intValue();
                }catch(ClassCastException e){
                    continue;
                }
                if (best == null || val > best) best = val;
            }
        }
        result.add(best);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) throw new IllegalArgumentException("keys list cannot be null");
    List<Integer> result = new ArrayList<>();
    try {
        List<Integer> intKeys = new ArrayList<>(keys.size());
        for (K k : keys) {
            if (k == null) throw new IllegalArgumentException("key cannot be null");
            if (!(k instanceof Integer)) throw new IllegalArgumentException("key is not an Integer");
            intKeys.add((Integer) k);
        }
        List<Integer> sorted = new ArrayList<>(intKeys);
        Collections.sort(sorted);
        for (Integer key : intKeys) {
            int idx = Collections.binarySearch(sorted, key);
            if (idx < 0) {
                idx = -idx - 1;
            }
            int lowerIdx = idx - 1;
            Integer lowerBound = (lowerIdx >= 0) ? sorted.get(lowerIdx) : null;
            result.add(lowerBound);
        }
    } catch (RuntimeException e) {
        throw new RuntimeException("Failed to compute lower bounds", e);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new java.util.ArrayList<>(keys != null ? keys.size() : 0);
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    try {
        java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
        for (K key : keys) {
            set.add((Integer) key);
        }
        for (K key : keys) {
            Integer lower = set.lower((Integer) key);
            lowerBounds.add(lower);
        }
    } catch (ClassCastException e) {
        // If keys are not Integers, return null for each bound
        for (int i = 0; i < keys.size(); i++) {
            lowerBounds.add(null);
        }
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    // Convert keys to integers (if possible)
    List<Integer> intKeys = new ArrayList<>(keys.size());
    for (K k : keys) {
        if (k == null) {
            intKeys.add(null);
        } else {
            try {
                intKeys.add(Integer.valueOf(k.toString()));
            } catch (NumberFormatException e) {
                intKeys.add(null);
            }
        }
    }
    // Prepare a sorted list of indices based on the integer values
    List<Integer> sortedIndices = new ArrayList<>();
    for (int i = 0; i < intKeys.size(); i++) {
        if (intKeys.get(i) != null) {
            sortedIndices.add(i);
        }
    }
    sortedIndices.sort(Comparator.comparing(i -> intKeys.get(i)));
    // Map each index to its maximum lower bound (previous value in sorted order)
    Map<Integer, Integer> lowerBoundMap = new HashMap<>();
    Integer previous = null;
    for (int idx : sortedIndices) {
        Integer key = intKeys.get(idx);
        lowerBoundMap.put(idx, previous != null ? previous : Integer.MIN_VALUE);
        previous = key;
    }
    // Build result list maintaining original order
    for (int i = 0; i < keys.size(); i++) {
        bounds.add(lowerBoundMap.getOrDefault(i, Integer.MIN_VALUE));
    }
    return bounds;
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new NullPointerException("descriptor");
    }
    int len = descriptor.length();
    if (len == 0) {
        return;
    }
    // Helper to pop one type from the stack
    Runnable popOne = () -> {
        if (pos == 0) {
            throw new IllegalStateException("Stack underflow while popping");
        }
        pos--;
    };
    // If descriptor represents a method descriptor
    if (descriptor.charAt(0) == '(') {
        int i = 1; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            // Consume a type
            char c = descriptor.charAt(i);
            if (c == '[') {
                // Consume all '['
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now consume the element type
                if (i >= len) {
                    throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                }
                char inner = descriptor.charAt(i);
                if (inner == 'L') {
                    i++; // skip 'L'
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= len) {
                        throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                    }
                    i++; // skip ';'
                } else {
                    // Primitive type inside array
                    i++; // consume primitive
                }
            } else if (c == 'L') {
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                }
                i++; // skip ';'
            } else {
                // Primitive type
                i++; // consume one char
            }
            popOne.run();
        }
    } else {
        // Single type descriptor
        int i = 0;
        char c = descriptor.charAt(i);
        if (c == '[') {
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
            }
            char inner = descriptor.charAt(i);
            if (inner == 'L') {
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                }
                i++; // skip ';'
            } else {
                i++; // consume primitive
            }
        } else if (c == 'L') {
            i++; // skip 'L'
            while (i < len && descriptor.charAt(i) != ';') {
                i++;
            }
            if (i >= len) {
                throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
            }
            i++; // skip ';'
        } else {
            i++; // primitive
        }
        popOne.run();
    }
}

private void pop(final String descriptor) {
    // Assume a stack array `stack` and a pointer `pos` are fields of the surrounding class.
    // The method pops the appropriate number of slots from the stack based on the descriptor.
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int idx = 0;
    int end = descriptor.length();

    // Handle method descriptor: skip the parameters part.
    if (descriptor.charAt(0) == '(') {
        int closeParen = descriptor.indexOf(')');
        if (closeParen < 0) {
            throw new IllegalArgumentException("Invalid descriptor: missing ')'");
        }
        idx = 1;
        end = closeParen;
    }

    while (idx < end) {
        int slots = 1; // default slot count

        // Handle array dimensions
        while (idx < end && descriptor.charAt(idx) == '[') {
            idx++;
        }

        if (idx >= end) {
            throw new IllegalArgumentException("Invalid descriptor: truncated type");
        }

        char type = descriptor.charAt(idx);

        switch (type) {
            case 'J': // long
            case 'D': // double
                slots = 2;
                break;
            case 'L':
                int semi = descriptor.indexOf(';', idx);
                if (semi < 0) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                idx = semi; // will be incremented below
                break;
            case 'V': // void – should never appear as an argument but ignore safely
                slots = 0;
                break;
            default: // primitives: B C F I S Z
                // no special handling needed
                break;
        }

        idx++; // move past the type character (or ';' for object type)

        // Pop the calculated number of slots.
        for (int s = 0; s < slots; s++) {
            pos--; // move the pointer downwards
            if (pos >= 0 && stack != null) {
                stack[pos] = null; // clear reference for GC safety
            }
        }
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int idx = 0;
    int count = 0;
    if (descriptor.charAt(0) == '('){
        // method descriptor: pop each argument type
        while (descriptor.charAt(idx) != ')'){
            char c = descriptor.charAt(idx);
            if (c == 'L'){
                // object type: consume up to ';'
                idx = descriptor.indexOf(';', idx) + 1;
            } else if (c == '['){
                // array: consume the '[' and continue to base type
                idx++;
                continue;
            } else {
                idx++;
            }
            count++;
        }
        // skip ')'
        idx++;
    } else {
        // single type descriptor: pop one
        count = 1;
    }
    // Adjust the stack pointer (assumes a field named 'pos' holds the current stack index)
    pos -= count;
}

