private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null) {
        return upperBounds;
    }
    for (K key : keys) {
        if (key == null) {
            upperBounds.add(0);
            continue;
        }
        if (key instanceof Number) {
            // Use the numeric value as an upper bound
            upperBounds.add(((Number) key).intValue());
        } else {
            // Fallback: use the hash code of the key as a proxy value
            upperBounds.add(key.hashCode());
        }
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        int bound = (key == null) ? 0 : key.hashCode();
        bounds.add(bound);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new java.util.ArrayList<>();
    if (keys == null){
        return bounds;
    }
    for (K key : keys){
        try{
            if (key == null){
                bounds.add(0);
            } else {
                bounds.add(key.hashCode());
            }
        } catch (Exception e){
            // In case hashCode throws an exception, fall back to 0
            bounds.add(0);
        }
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) throw new IllegalArgumentException("keys must not be null");
    List<Integer> result = new ArrayList<>();
    List<Integer> intKeys = new ArrayList<>();
    for (K k : keys) {
        if (k == null) throw new IllegalArgumentException("key cannot be null");
        if (!(k instanceof Integer)) throw new IllegalArgumentException("keys must be Integers");
        intKeys.add((Integer) k);
    }
    List<Integer> sorted = new ArrayList<>(intKeys);
    Collections.sort(sorted);
    for (Integer val : intKeys) {
        int idx = Collections.binarySearch(sorted, val);
        if (idx < 0) idx = -idx - 1;
        int upper = Integer.MAX_VALUE;
        if (idx + 1 < sorted.size()) upper = sorted.get(idx + 1);
        result.add(upper);
    }
    return result;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return bounds;
    }
    for (K key : keys){
        try{
            if (key instanceof Integer){
                bounds.add((Integer) key);
            } else if (key instanceof Number){
                bounds.add(((Number) key).intValue());
            } else {
                bounds.add(0);
            }
        } catch (Exception e){
            bounds.add(0);
        }
    }
    return bounds;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        switch (c) {
            case '{':
                sb.append("%7B");
                break;
            case '}':
                sb.append("%7D");
                break;
            default:
                sb.append(c);
                break;
        }
    }
    return sb.toString();
}

