public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    try {
        boolean isAbsolute = path.startsWith("/");
        String[] baseParts = path.split("/");
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : baseParts) {
            if (part.isEmpty() || ".".equals(part)) {
                continue;
            }
            stack.add(part);
        }
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || ".".equals(part)) {
                continue;
            }
            if ("..".equals(part)) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                }
            } else {
                stack.add(part);
            }
        }
        StringBuilder result = new StringBuilder();
        if (isAbsolute) {
            result.append('/');
        }
        for (int i = 0; i < stack.size(); i++) {
            result.append(stack.get(i));
            if (i < stack.size() - 1) {
                result.append('/');
            }
        }
        if (isAbsolute && result.length() == 0) {
            result.append('/');
        }
        return result.toString();
    } catch (Exception e) {
        throw new IllegalArgumentException("Unable to apply relative path", e);
    }
}

public static String applyRelativePath(String path,String relativePath){
    // Basic validation
    if (path == null && relativePath == null) return null;
    if (path == null) return relativePath;
    if (relativePath == null) return path;

    // Split path into components
    String[] baseParts = path.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Populate stack with base components (skip empty strings caused by leading '/')
    for (String part : baseParts) {
        if (part.length() == 0) continue; // skip empty
        if (part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.pollLast();
        } else {
            stack.offerLast(part);
        }
    }

    // Process relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.length() == 0 || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.pollLast();
        } else {
            stack.offerLast(part);
        }
    }

    // Build result
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/")) result.append("/");
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) result.append("/");
    }

    String resStr = result.toString();
    // Ensure at least "/" is returned for root
    if (resStr.isEmpty()) return "/";
    return resStr;
}

public static String applyRelativePath(String path, String relativePath) {
    // Validate parameters
    if (path == null) {
        throw new IllegalArgumentException("path must not be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath must not be null");
    }
    try {
        // Normalize separators for relativePath (allow backslashes as well)
        String rel = relativePath.replace("\\", "/");
        // Resolve relative path against base path
        java.nio.file.Path base = java.nio.file.Paths.get(path).toAbsolutePath();
        java.nio.file.Path resolved = base.resolve(rel).normalize();
        // Convert to a String with forward slashes
        String result = resolved.toString().replace("\\", "/");
        return result;
    } catch (Exception e) {
        throw new RuntimeException("Failed to apply relative path", e);
    }
}

