public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return null;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    String[] baseParts = path.split("/", -1);
    String[] relParts = relativePath.split("/", -1);

    // Max possible parts: base + relative
    String[] stack = new String[baseParts.length + relParts.length];
    int stackSize = 0;

    // Add base parts to stack, ignoring empty parts (which occur due to leading '/')
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (stackSize > 0) {
                stackSize--;
            }
            continue;
        }
        stack[stackSize++] = part;
    }

    // Apply relative parts
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (stackSize > 0) {
                stackSize--;
            }
            continue;
        }
        stack[stackSize++] = part;
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    boolean hasLeadingSlash = path.startsWith("/");
    if (hasLeadingSlash) {
        result.append("/");
    }
    for (int i = 0; i < stackSize; i++) {
        result.append(stack[i]);
        if (i < stackSize - 1) {
            result.append("/");
        }
    }

    // If the result is empty (e.g., navigating to root), preserve slash if needed
    if (result.length() == 0 && hasLeadingSlash) {
        result.append("/");
    }
    return result.toString();
}

