static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    int length = array.length;
    for (int i = 0; i < length; i++) {
        if (array[i] != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == length) { // no nulls present
        // If array is actually a String[] instance, return it directly
        if (array instanceof String[]) {
            return (String[]) array;
        }
        // otherwise create a new String[] from the elements
        String[] result = new String[length];
        for (int i = 0; i < length; i++) {
            result[i] = (String) array[i];
        }
        return result;
    }
    // Build a new array without null values
    if (nonNullCount == 0) {
        return new String[0];
    }
    String[] result = new String[nonNullCount];
    int j = 0;
    for (int i = 0; i < length; i++) {
        Object obj = array[i];
        if (obj != null) {
            result[j++] = (String) obj;
        }
    }
    return result;
}

